<?php

declare(strict_types=1);

namespace App\Tests\Entity;

use Doctrine\ORM\EntityManagerInterface;
use Doctrine\ORM\Tools\SchemaValidator;
use Symfony\Bundle\FrameworkBundle\Test\KernelTestCase;

final class SchemaDriftTest extends KernelTestCase
{
    private const string MIGRATIONS_BUNDLE_TABLE = 'doctrine_migration_versions';

    private const array EXPECTED_SCHEMA_DIFFERENCE = [
        'ALTER TABLE brand ALTER id ADD GENERATED BY DEFAULT AS IDENTITY',
        'ALTER TABLE car_model ALTER id ADD GENERATED BY DEFAULT AS IDENTITY',
        'ALTER TABLE import_run ALTER id ADD GENERATED BY DEFAULT AS IDENTITY',
        'ALTER TABLE variant ALTER id ADD GENERATED BY DEFAULT AS IDENTITY',
        'ALTER TABLE version ALTER id ADD GENERATED BY DEFAULT AS IDENTITY',
    ];

    public function testMappingIsInternallyValid(): void
    {
        self::bootKernel();
        $entityManager = self::getContainer()->get(EntityManagerInterface::class);
        $validator = new SchemaValidator($entityManager);

        self::assertSame([], $validator->validateMapping());
    }

    public function testDifferenceAgainstTheLiveSchemaEqualsTheKnownAcceptableList(): void
    {
        self::bootKernel();
        $entityManager = self::getContainer()->get(EntityManagerInterface::class);
        $validator = new SchemaValidator($entityManager);

        $actual = self::excludingMigrationsBundleTable($validator->getUpdateSchemaList());
        $expected = self::EXPECTED_SCHEMA_DIFFERENCE;

        sort($actual);
        sort($expected);

        self::assertSame($expected, $actual);
    }

    /**
     * @param array<array-key, string> $statements
     *
     * @return list<string>
     */
    private static function excludingMigrationsBundleTable(array $statements): array
    {
        return array_values(array_filter(
            $statements,
            static fn (string $statement): bool => !str_contains($statement, self::MIGRATIONS_BUNDLE_TABLE),
        ));
    }
}
